WITH cp AS (
  UPDATE company_profile SET industry = $1, staff_enabled = $2::boolean, staff_label = $3, booking_hours = $4::jsonb, updated_at = now() WHERE id = 1 RETURNING id
), added AS (
  INSERT INTO event_types (key, name, color, sort_order)
  SELECT x.t->>'key', x.t->>'name', x.t->>'color', (SELECT COALESCE(max(sort_order), 0) FROM event_types) + x.ord::int
  FROM jsonb_array_elements($5::jsonb) WITH ORDINALITY AS x(t, ord)
  ON CONFLICT DO NOTHING RETURNING id
), ren AS (
  -- Only the untouched default name is replaced; a name the customer chose is never overwritten.
  UPDATE event_types SET name = $6 WHERE key = 'meeting' AND name = 'Meeting' AND $6 <> 'Meeting'
    AND NOT EXISTS (SELECT 1 FROM event_types e2 WHERE lower(e2.name) = lower($6)) RETURNING id
)
SELECT (SELECT count(*) FROM cp)::int AS updated, (SELECT count(*) FROM added)::int AS types_added, (SELECT count(*) FROM ren)::int AS renamed;

