const headers = $('Webhook: save-industry-features').first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');

return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active } }];

const requester = $input.first().json;
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only an admin can change industry and features.');
const body = $('Webhook: save-industry-features').first().json.body || {};
const bool = (v) => (v === true || v === 'true' ? true : v === false || v === 'false' ? false : null);
const staffEnabled = bool(body.staff_enabled);
const onlineChoice = bool(body.online_provider_choice);
let staffLabel = typeof body.staff_label === 'string' ? body.staff_label.replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 30) : null;
if (staffLabel === '') staffLabel = null;
let hours = null;
if (body.booking_hours && typeof body.booking_hours === 'object') {
  const h = body.booking_hours;
  const start = parseInt(h.start, 10), end = parseInt(h.end, 10), slot = parseInt(h.slot_minutes, 10);
  const step = h.step_minutes === undefined || h.step_minutes === null || h.step_minutes === '' ? slot : parseInt(h.step_minutes, 10);
  const buffer = h.buffer_minutes === undefined || h.buffer_minutes === null || h.buffer_minutes === '' ? 0 : parseInt(h.buffer_minutes, 10);
  const days = Array.isArray(h.days) ? [...new Set(h.days.map((d) => parseInt(d, 10)).filter((d) => d >= 0 && d <= 6))].sort() : null;
  if (!(start >= 0 && start <= 23 && end >= 1 && end <= 24 && end > start)) throw new Error('Closing time must be after opening time.');
  if (![15, 20, 30, 45, 60, 90, 120].includes(slot)) throw new Error('Choose a slot length from the list.');
  if (![15, 20, 30, 45, 60, 90, 120].includes(step)) throw new Error('Choose a start-time step from the list.');
  if (![0, 5, 10, 15, 30, 45, 60].includes(buffer)) throw new Error('Choose a gap from the list.');
  if (!days || days.length === 0) throw new Error('Choose at least one open day.');
  hours = JSON.stringify({ start, end, days, slot_minutes: slot, step_minutes: step, buffer_minutes: buffer, lead_hours: Math.min(72, Math.max(0, parseInt(h.lead_hours, 10) || 2)), window_days: Math.min(60, Math.max(1, parseInt(h.window_days, 10) || 14)) });
}
return [{ json: { staffEnabled, onlineChoice, staffLabel, hours } }];
